# PowerShell Script to Fix Virtual Environment Permission Issues
# Run this script in PowerShell (NOT as Administrator)

Write-Host "🔧 Fixing PowerShell Virtual Environment Setup..." -ForegroundColor Cyan

# Check if running as Administrator
$currentPrincipal = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
$isAdmin = $currentPrincipal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)

if ($isAdmin) {
    Write-Host "❌ ERROR: This script should NOT be run as Administrator!" -ForegroundColor Red
    Write-Host "Please close this PowerShell window and open a new one WITHOUT Administrator privileges." -ForegroundColor Yellow
    Write-Host "Then run this script again." -ForegroundColor Yellow
    Read-Host "Press Enter to exit"
    exit 1
}

Write-Host "✅ Running with normal user privileges (correct)" -ForegroundColor Green

# Set execution policy for current user if needed
try {
    $currentPolicy = Get-ExecutionPolicy -Scope CurrentUser
    if ($currentPolicy -eq "Restricted") {
        Write-Host "📋 Setting PowerShell execution policy..." -ForegroundColor Yellow
        Set-ExecutionPolicy -ExecutionPolicy RemoteSigned -Scope CurrentUser -Force
        Write-Host "✅ Execution policy set to RemoteSigned for current user" -ForegroundColor Green
    }
} catch {
    Write-Host "⚠️ Could not set execution policy: $($_.Exception.Message)" -ForegroundColor Yellow
}

# Navigate to project directory
$projectPath = "C:\projects\SignalSniper"
if (-not (Test-Path $projectPath)) {
    Write-Host "❌ Project directory not found: $projectPath" -ForegroundColor Red
    exit 1
}

Set-Location $projectPath
Write-Host "📁 Working in: $(Get-Location)" -ForegroundColor Blue

# Remove existing venv directory if it exists
$venvPath = Join-Path $projectPath "venv"
if (Test-Path $venvPath) {
    Write-Host "🗑️ Removing existing venv directory with permission issues..." -ForegroundColor Yellow
    try {
        # Try to remove normally first
        Remove-Item -Path $venvPath -Recurse -Force -ErrorAction Stop
        Write-Host "✅ Successfully removed old venv directory" -ForegroundColor Green
    } catch {
        Write-Host "⚠️ Standard removal failed, trying alternative method..." -ForegroundColor Yellow
        try {
            # Use takeown and icacls to fix permissions then remove
            & takeown /f $venvPath /r /d y 2>$null
            & icacls $venvPath /grant "$env:USERNAME:(F)" /t 2>$null
            Remove-Item -Path $venvPath -Recurse -Force -ErrorAction Stop
            Write-Host "✅ Successfully removed old venv directory with permission fix" -ForegroundColor Green
        } catch {
            Write-Host "❌ Could not remove venv directory: $($_.Exception.Message)" -ForegroundColor Red
            Write-Host "You may need to manually delete the venv folder or restart your computer" -ForegroundColor Yellow
            Read-Host "Press Enter to continue anyway"
        }
    }
}

# Check Python installation
Write-Host "🐍 Checking Python installation..." -ForegroundColor Blue
try {
    $pythonVersion = python --version 2>&1
    Write-Host "✅ Python found: $pythonVersion" -ForegroundColor Green
} catch {
    Write-Host "❌ Python not found in PATH" -ForegroundColor Red
    Write-Host "Please install Python from https://python.org or ensure it's in your PATH" -ForegroundColor Yellow
    Read-Host "Press Enter to exit"
    exit 1
}

# Create new virtual environment
Write-Host "🔨 Creating new virtual environment..." -ForegroundColor Blue
try {
    python -m venv venv
    Write-Host "✅ Virtual environment created successfully" -ForegroundColor Green
} catch {
    Write-Host "❌ Failed to create virtual environment: $($_.Exception.Message)" -ForegroundColor Red
    Read-Host "Press Enter to exit"
    exit 1
}

# Activate virtual environment
Write-Host "🚀 Activating virtual environment..." -ForegroundColor Blue
$activateScript = Join-Path $venvPath "Scripts\Activate.ps1"
if (Test-Path $activateScript) {
    try {
        & $activateScript
        Write-Host "✅ Virtual environment activated" -ForegroundColor Green
    } catch {
        Write-Host "❌ Failed to activate virtual environment: $($_.Exception.Message)" -ForegroundColor Red
        Write-Host "Trying alternative activation method..." -ForegroundColor Yellow
        $env:VIRTUAL_ENV = $venvPath
        $env:PATH = "$venvPath\Scripts;$env:PATH"
        Write-Host "✅ Virtual environment activated (alternative method)" -ForegroundColor Green
    }
} else {
    Write-Host "❌ Activation script not found: $activateScript" -ForegroundColor Red
    exit 1
}

# Upgrade pip
Write-Host "📦 Upgrading pip..." -ForegroundColor Blue
try {
    python -m pip install --upgrade pip
    Write-Host "✅ Pip upgraded successfully" -ForegroundColor Green
} catch {
    Write-Host "⚠️ Pip upgrade failed: $($_.Exception.Message)" -ForegroundColor Yellow
}

# Install requirements
Write-Host "📚 Installing Python dependencies..." -ForegroundColor Blue
$requirementsFile = Join-Path $projectPath "requirements.txt"
if (Test-Path $requirementsFile) {
    try {
        pip install -r requirements.txt
        Write-Host "✅ Dependencies installed successfully" -ForegroundColor Green
    } catch {
        Write-Host "❌ Failed to install dependencies: $($_.Exception.Message)" -ForegroundColor Red
        Write-Host "You may need to install dependencies manually" -ForegroundColor Yellow
    }
} else {
    Write-Host "⚠️ requirements.txt not found, installing essential packages..." -ForegroundColor Yellow
    try {
        pip install telethon python-dotenv pytz asyncio
        Write-Host "✅ Essential packages installed" -ForegroundColor Green
    } catch {
        Write-Host "❌ Failed to install essential packages: $($_.Exception.Message)" -ForegroundColor Red
    }
}

# Test the setup
Write-Host "🧪 Testing the setup..." -ForegroundColor Blue
try {
    python -c "import telethon, dotenv, pytz; print('✅ All essential modules imported successfully')"
    Write-Host "✅ Python environment is working correctly" -ForegroundColor Green
} catch {
    Write-Host "❌ Python environment test failed: $($_.Exception.Message)" -ForegroundColor Red
}

Write-Host ""
